{
  "case_id": "xsu_sg_003_severity_assessment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret nævner individuel vurdering og påvirkning af daglig funktion. Men det udelader helt behandling, effekt, restsymptomer og medvirken, og kravet om lægefaglig dokumentation. Det tilføjer også 'funktionsvurdering' som en særlig metode og erhvervs-/uddannelsesevne som moment, uden støtte i kilderne. Det er væsentlige juridiske mangler og fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Det kritiske element om relevant behandling, behandlingseffekt, restsymptomer/bivirkninger og rimelig medvirken mangler. Elementet om lægefagligt dokumenteret grundlag mangler. Varighed er kun delvist dækket, da gentagne sygdomsperioder og tilbagefaldsrisiko mangler."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret forholder sig direkte til, hvad Udbetaling Danmark lægger vægt på ved sværhedsgraden. Det er delvist unøjagtigt, men det besvarer spørgsmålet og er ikke fyldt ud med irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde, hverken bestemmelse, vejledning eller lov."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ingen angivne kilder, så støtte til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en 'særlig vurderingsmetode kaldet funktionsvurdering', der omfatter fysisk, psykisk og social funktionsevne, uden støtte i materialet. Det fremhæver også behov for hjælp fra andre, deltagelse i uddannelse eller arbejde og 'andre faktorer' som smerter og træthed. Det påstår desuden, at Udbetaling Danmark 'altid' foretager en fair vurdering."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fremstiller en liste som de forhold, der lægges vægt på, uden at markere dem som eksempler ('f.eks.'/'blandt andet'). Det understreger dog, at vurderingen er individuel. Men det mangler, at momenterne indgår i en samlet vurdering af lægefagligt beskrevne aktuelle symptomer. Listen virker udtømmende."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende: det opregner momenter og konkluderer, at vurderingen er individuel og kompleks. Der er ingen indbyrdes modstrid, selv om indholdet er mangelfuldt."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret fremstiller momenterne som en fast opregning af, hvad Udbetaling Danmark 'lægger vægt på'. Kilden siger, at de indgår 'f.eks.'. Svaret hævder desuden, at myndigheden 'altid' vurderer fair og bruger en bestemt metode. Det gør skønsprægede elementer for absolutte."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "no",
      "reason": "Svaret siger intet om, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret, og det nævner ikke journaler eller lægefaglige oplysninger. Det dækker heller ikke behandling, restsymptomer eller sygdomshistorik. Kun den generelle påvirkning af hverdagen svarer til noget i punktet."
    }
  },
  "overall_notes": "Svaret er generisk og uden kilde. Det rammer kun påvirkningen af daglig funktion og delvist varighed. Det udelader behandling, restsymptomer, medvirken, gentagelser, tilbagefaldsrisiko og lægefaglig dokumentation. Det tilføjer ustøttede elementer som 'funktionsvurdering' og fremstår som en fast liste."
}

